FROM t_pending_order_trigger
WHERE user_id = #{userId} AND order_type != 5
AND symbol = #{symbol}
AND status = #{status}
AND status = 1
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

