UPDATE t_pending_order_trigger
SET status        = 3,
    cancelled_at  = #{updatedAt},
    cancel_reason = #{cancelReason},
    updated_at    = #{updatedAt}
WHERE parent_position_id = #{positionId}
  AND order_type = 5
  AND trigger_kind = #{triggerKind}
  AND status = 1
